<!DOCTYPE html>
<html lang="hu">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Booking Agent UI</title>
  <script src=""></script>
  <style>
    @keyframes spin {
      from {
        transform: rotate(0deg);
      }

      to {
        transform: rotate(360deg);
      }
    }

    .animate-spin {
      animation: spin 1s linear infinite;
    }

    .fade-in-up {
      animation: fadeInUp 0.5s ease-out forwards;
    }

    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(10px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .transition-all {
      transition-property: all;
      transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
      transition-duration: 500ms;
    }

    .hidden-element {
      display: none;
    }

    /* Apple-like font smoothing */
    body {
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }
  </style>
</head>

<body class="min-h-screen flex items-center justify-center p-4 m-0 font-sans text-white"
  style="background-color: #000; background-image: radial-gradient(circle at 50% 50%, #002266 0%, #000000 85%); background-attachment: fixed;">
  <div class="w-full max-w-4xl mx-auto select-none">
    <div
      class="relative flex aspect-[1/1.5] w-full items-center justify-center rounded-2xl border border-white/20 bg-black/40 backdrop-blur-xl sm:aspect-[4/3] lg:aspect-video overflow-hidden shadow-2xl ring-1 ring-white/10">
      <div id="step1"
        class="absolute inset-0 flex items-center justify-center transition-opacity duration-500 opacity-0">
        <div
          class="flex w-full max-w-[90%] flex-col divide-y divide-white/10 overflow-hidden rounded-3xl border border-white/20 bg-black shadow-2xl shadow-blue-900/20 md:max-w-2xl md:flex-row md:divide-x md:divide-y-0 backdrop-blur-md">
          <div class="flex grow flex-col justify-between gap-4 p-6">
            <div class="flex size-12 items-center justify-center rounded-xl border border-white/20 bg-white/10 shadow-inner">
              <svg xmlns="" fill="none" viewBox="0 0 24 24"
                stroke-width="1.5" stroke="currentColor" class="w-6 h-6 text-white">
                <path stroke-linecap="round" stroke-linejoin="round"
                  d="M3.75 21h16.5M4.5 3h15M5.25 3v18m13.5-18v18M9 6.75h1.5m-1.5 3h1.5m-1.5 3h1.5m3-6H15m-1.5 3H15m-1.5 3H15M9 21v-3.375c0-.621.504-1.125 1.125-1.125h3.75c.621 0 1.125.504 1.125 1.125V21" />
              </svg>
            </div>
            <div>
              <div class="mb-2"><span class="text-white text-xl font-semibold tracking-tight">Foglalási Asszisztens</span></div>
              <div>
                <p class="text-neutral-400 text-sm leading-relaxed">Ön egy szállodai ügyfélszolgálati munkatárs, aki segít a vendégeknek foglalásokat intézni és általános kérdésekre válaszolni.</p>
              </div>
            </div>
          </div>
          <div class="shrink-0 bg-white/5 p-6 md:w-[260px]">
            <div class="mb-4"><span class="text-neutral-500 text-xs font-semibold uppercase tracking-wider">Elérhető eszközök</span></div>
            <div class="space-y-3" id="tool-list"></div>
          </div>
        </div>
      </div>

      <div id="chat-interface" class="absolute inset-0 flex flex-col p-6 transition-opacity duration-500 opacity-0">
        <div class="relative flex h-full flex-col">
          <div class="grow space-y-8">
            <div class="flex justify-end">
              <div
                class="rounded-[20px] rounded-br-sm bg-[#0066ff] px-5 py-3 text-[15px] text-white shadow-[0_0_15px_rgba(0,102,255,0.3)] font-medium tracking-tight">
                Szia! Szeretném frissíteni a jelenlegi foglalásomat Executive lakosztályra.
              </div>
            </div>

            <div class="relative h-10 w-full md:h-6 pl-2" id="status-container"></div>

            <div id="user-thanks" class="flex justify-end transition-opacity duration-300 opacity-0">
              <div
                class="rounded-[20px] rounded-br-sm bg-[#0066ff] px-5 py-3 text-[15px] text-white shadow-[0_0_15px_rgba(0,102,255,0.3)] font-medium tracking-tight">
                Köszönöm!
              </div>
            </div>
          </div>

          <div class="absolute bottom-0 left-0">
            <div class="w-[220px] shrink-0 rounded-2xl border border-white/20 bg-black/90 backdrop-blur-md p-5 shadow-xl">
              <div class="mb-3"><span class="text-neutral-500 text-xs font-semibold uppercase tracking-wider">Cselekvési terv</span>
              </div>
              <div class="space-y-3" id="plan-list"></div>
            </div>
          </div>

          <div class="absolute bottom-0 right-0 hidden md:flex flex-col items-end gap-4 pointer-events-none"
            id="eval-container"></div>
        </div>
      </div>

    </div>
  </div>

  <script>
    const tools = [
      {tag: "client-tool", text: "Vendég keresése e-mail alapján", icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'},
      {tag: "server-code", text: "Foglalási részletek lekérése", icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'},
      {tag: "web-search", text: "Szabad szobák keresése", icon: 'm21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z'},
      {tag: "client-tool", text: "Foglalás módosítása", icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'}
    ];

    const plans = [
      {id: 1, text: "Vendég azonosítása", trigger: 4, done: 5},
      {id: 2, text: "Elérhetőség ellenőrzése", trigger: 6, done: 7},
      {id: 3, text: "Foglalás frissítése", trigger: 8, done: 9}
    ];

    const evals = [
      {step: 5, tag: "client-tool", name: "Vendég keresése e-mail alapján", input: "john.doe@example.com", output: "User ID: 1234567890", icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'},
      {step: 7, tag: "web-search", name: "Szabad szobák keresése", input: "Executive lakosztály", output: "Room ID: 2918482", icon: 'm21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z'},
      {step: 9, tag: "client-tool", name: "Foglalás módosítása", input: "BX-23929", output: null, icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'}
    ];

    const toolList = document.getElementById('tool-list');
    tools.forEach(t => {
      toolList.innerHTML += `
            <div class="flex items-center gap-3">
                <div class="flex size-9 items-center justify-center rounded-lg border border-white/10 bg-white/5">
                    <svg xmlns="" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-4 h-4 text-zinc-100">
                        <path stroke-linecap="round" stroke-linejoin="round" d="${t.icon}" />
                    </svg>
                </div>
                <div class="flex flex-col space-y-0.5">
                    <span class="text-[10px] text-neutral-500 font-mono bg-white/10 px-1.5 py-0.5 rounded w-fit uppercase tracking-wide border border-white/5">${t.tag}</span>
                    <span class="text-zinc-300 block text-xs font-medium">${t.text}</span>
                </div>
            </div>`;
    });

    function updateUI(step) {
      const step1 = document.getElementById('step1');
      const chatInterface = document.getElementById('chat-interface');
      const statusContainer = document.getElementById('status-container');
      const planList = document.getElementById('plan-list');
      const evalContainer = document.getElementById('eval-container');
      const userThanks = document.getElementById('user-thanks');

      step1.style.opacity = (step === 1) ? "1" : "0";
      chatInterface.style.opacity = (step >= 2) ? "1" : "0";

      let statusHTML = '';
      if (step === 3) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><span class="text-zinc-400 text-[15px]">Rendben, egy pillanat, megkeresem a foglalást...</span></div>';
      else if (step >= 4 && step < 6) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><svg class="w-4 h-4 text-blue-500 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5"/></svg><span class="text-zinc-200 text-[15px] font-medium">Fiók keresése...</span></div>';
      else if (step >= 6 && step < 8) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><svg class="w-4 h-4 text-blue-500 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/></svg><span class="text-zinc-200 text-[15px] font-medium">Elérhető szobák keresése...</span></div>';
      else if (step >= 8 && step < 10) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><svg class="w-4 h-4 text-blue-500 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5"/></svg><span class="text-zinc-200 text-[15px] font-medium">Foglalás frissítése Executive lakosztályra...</span></div>';
      else if (step >= 10) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><span class="text-zinc-100 text-[15px]">Rendben, kész is. A foglalásod mostantól az Executive lakosztályra szól – kellemes pihenést kívánok!</span></div>';
      statusContainer.innerHTML = statusHTML;

      planList.innerHTML = '';
      plans.forEach(p => {
        const isActive = step >= p.trigger && step < p.done;
        const isDone = step >= p.done;
        planList.innerHTML += `
                <div class="flex items-center gap-3">
                    <div class="relative flex size-6 items-center justify-center rounded-full border ${isActive ? 'border-blue-500 bg-blue-500/10' : 'border-white/10 bg-white/5'}">
                        <span class="text-xs ${isActive ? 'text-blue-400 font-bold' : 'text-neutral-500'}">${p.id}</span>
                        ${isActive ? '<div class="absolute inset-0 flex items-center justify-center rounded-full"><svg class="w-full h-full p-1 animate-spin text-blue-500" viewBox="0 0 24 24" fill="none"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg></div>' : ''}
                        ${isDone ? '<div class="absolute inset-0 flex items-center justify-center rounded-full bg-blue-600 border border-blue-600"><svg class="w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="m4.5 12.75 6 6 9-13.5"/></svg></div>' : ''}
                    </div>
                    <div><span class="text-[13px] font-medium transition-colors ${step >= p.trigger ? 'text-white' : 'text-neutral-500'}">${p.text}</span></div>
                </div>`;
      });

      evalContainer.innerHTML = '';
      evals.forEach(e => {
        if (step >= e.step) {
          evalContainer.innerHTML += `
                    <div class="transition-all transform opacity-100 translate-y-0">
                        <div class="min-w-[280px] shrink-0 space-y-3 rounded-2xl border border-white/20 bg-black/90 backdrop-blur-md p-4 shadow-xl">
                            <div class="flex items-center gap-3">
                                <div class="flex size-8 items-center justify-center rounded-lg border border-white/10 bg-white/5">
                                    <svg class="w-4 h-4 text-zinc-100" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" d="${e.icon}"/></svg>
                                </div>
                                <div class="flex flex-col"><span class="text-[10px] text-neutral-500 font-mono uppercase tracking-wide">${e.tag}</span><span class="text-zinc-100 text-[13px] font-medium">${e.name}</span></div>
                            </div>
                            <div class="space-y-2 bg-white/5 rounded-lg p-2.5 border border-white/5">
                                <div class="flex justify-between text-[11px]"><span class="text-neutral-500 font-medium">Érkezès</span><span class="text-zinc-300 font-mono">${e.input}</span></div>
                                ${e.output ? `<div class="h-px bg-white/5 my-1"></div><div class="flex justify-between text-[11px]"><span class="text-neutral-500 font-medium">Távozás</span><span class="text-blue-400 font-mono">${e.output}</span></div>` : ''}
                            </div>
                        </div>
                    </div>`;
        }
      });

      userThanks.style.opacity = (step >= 10) ? "1" : "0";
    }

    async function runAnimation() {
      const timings = [2000, 1000, 1000, 800, 800, 800, 800, 800, 800, 3000];
      while (true) {
        for (let i = 1; i <= 10; i++) {
          updateUI(i);
          await new Promise(r => setTimeout(r, timings[i - 1]));
        }
        updateUI(0);
        await new Promise(r => setTimeout(r, 500));
      }
    }

    runAnimation();
  </script>

</body>

</html>
